-- ============================================================
-- TechPro Inventory: schema + data import
-- Generated from task_category.sql (MySQL dump) -> Postgres/Supabase
-- Run this once in the Supabase SQL Editor for project sagjxhxtkqtbzzhudggj
-- ============================================================

-- ---------- Schema ----------
-- id columns use "generated by default as identity" so legacy ids can be
-- inserted explicitly below, while the app can still insert new rows later
-- without specifying an id (the sequence is fast-forwarded at the end).

create table if not exists public.tool_types (
  id integer primary key generated by default as identity,
  name text not null,
  created_at timestamptz default now()
);

create table if not exists public.brands (
  id integer primary key generated by default as identity,
  name text not null,
  created_at timestamptz default now()
);

create table if not exists public.companies (
  id integer primary key generated by default as identity,
  name text not null,
  created_at timestamptz default now()
);

create table if not exists public.machines (
  id integer primary key generated by default as identity,
  name text not null,
  created_at timestamptz default now()
);

create table if not exists public.app_users (
  id integer primary key generated by default as identity,
  name text not null,
  email text,
  created_at timestamptz default now()
);

-- No FK constraints on cross-table legacy id columns below: the source MySQL
-- dump has orphaned references (rows pointing at ids from tables/rows that no
-- longer exist upstream), so hard FKs would abort the data import.
create table if not exists public.inventory_items (
  id integer primary key generated by default as identity,
  name text not null,
  type_id integer,
  ordered integer not null default 0,
  issued integer not null default 0,
  balance_snapshot integer,
  threshold integer not null default 0,
  location text,
  returnable text not null default 'Returnable',
  essential boolean not null default false,
  created_at timestamptz default now()
);

create table if not exists public.inventory_orders (
  id integer primary key generated by default as identity,
  item_id integer,
  purchase_date date,
  qty_ordered integer not null default 0,
  previous_qty integer,
  total_qty integer,
  amount numeric not null default 0,
  assigned_to integer,
  document_name text,
  brand_id integer,
  company_id integer,
  confirmed boolean not null default false,
  created_at timestamptz default now()
);

create table if not exists public.inventory_assigned (
  id integer primary key generated by default as identity,
  item_id integer,
  user_id integer,
  issued_from_legacy text,
  source_location text,
  issued_date date,
  qty_issued integer not null default 0,
  balance_snapshot integer,
  remarks text,
  job_number text,
  drawing_number text,
  brand_id integer,
  machine_id integer,
  created_at timestamptz default now()
);

create table if not exists public.timeliness_configurations (
  id integer primary key generated by default as identity,
  report_name text not null,
  report_table text not null,
  frequency text not null,
  submission_day text not null,
  submitted_by integer,
  created_at timestamptz default now()
);

alter table public.tool_types enable row level security;
alter table public.brands enable row level security;
alter table public.companies enable row level security;
alter table public.machines enable row level security;
alter table public.app_users enable row level security;
alter table public.inventory_items enable row level security;
alter table public.inventory_orders enable row level security;
alter table public.inventory_assigned enable row level security;
alter table public.timeliness_configurations enable row level security;

do $$
declare
  t text;
begin
  for t in select unnest(array[
    'tool_types','brands','companies','machines','app_users',
    'inventory_items','inventory_orders','inventory_assigned',
    'timeliness_configurations'
  ])
  loop
    execute format('drop policy if exists "authenticated full access" on public.%I', t);
    execute format(
      'create policy "authenticated full access" on public.%I for all to authenticated using (true) with check (true)',
      t
    );
  end loop;
end $$;

