-- Fast-forward each identity sequence past the highest imported id, so the
-- app's own future inserts (which don't specify an id) never collide with
-- legacy ids above.
select setval(pg_get_serial_sequence('public.tool_types', 'id'), coalesce((select max(id) from public.tool_types), 0) + 1, false);
select setval(pg_get_serial_sequence('public.brands', 'id'), coalesce((select max(id) from public.brands), 0) + 1, false);
select setval(pg_get_serial_sequence('public.companies', 'id'), coalesce((select max(id) from public.companies), 0) + 1, false);
select setval(pg_get_serial_sequence('public.machines', 'id'), coalesce((select max(id) from public.machines), 0) + 1, false);
select setval(pg_get_serial_sequence('public.app_users', 'id'), coalesce((select max(id) from public.app_users), 0) + 1, false);
select setval(pg_get_serial_sequence('public.inventory_items', 'id'), coalesce((select max(id) from public.inventory_items), 0) + 1, false);
select setval(pg_get_serial_sequence('public.inventory_orders', 'id'), coalesce((select max(id) from public.inventory_orders), 0) + 1, false);
select setval(pg_get_serial_sequence('public.inventory_assigned', 'id'), coalesce((select max(id) from public.inventory_assigned), 0) + 1, false);
